CREATE FUNCTION public.club_city_key(p_city text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,pg_catalog AS $$ SELECT regexp_replace(translate(lower(normalize(coalesce(p_city,''),NFC) COLLATE pg_catalog."pg_c_utf8"),'áàâãäåéèêëíìîïóòôõöúùûüçñýÿ','aaaaaaeeeeiiiiooooouuuucnyy'),'[[:space:]]','','g') $$;
CREATE FUNCTION public.club_city_normalize(p_country text,p_city text) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE city text; country text:=upper(btrim(p_country)); BEGIN
 IF country IS NULL OR country='' THEN country:=NULL; END IF;
 IF p_city IS NULL OR btrim(p_city)='' THEN IF country IN ('PT','PORTUGAL') THEN RAISE EXCEPTION 'city_invalid'; END IF; RETURN NULL; END IF;
 IF length(p_city)>500 OR p_city ~ '[<>[:cntrl:]]' THEN RAISE EXCEPTION 'city_invalid'; END IF;
 city:=regexp_replace(btrim(normalize(p_city,NFC)),'[[:space:]]+',' ','g');
 IF length(city) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'city_invalid'; END IF;
 IF country IN ('PT','PORTUGAL') THEN SELECT min(name) INTO city FROM public.portugal_municipalities WHERE public.club_city_key(name)=public.club_city_key(p_city); IF city IS NULL THEN RAISE EXCEPTION 'city_unknown'; END IF;
 ELSE city:=initcap(lower(city COLLATE pg_catalog."pg_c_utf8")); END IF; RETURN city;
END $$;
CREATE FUNCTION public.club_cities() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ SELECT jsonb_build_object('country','PT','version','caop-2025','cities',jsonb_agg(jsonb_build_object('code',code,'name',name,'region',region) ORDER BY name,code)) FROM public.portugal_municipalities $$;
REVOKE EXECUTE ON FUNCTION public.club_city_key(text),public.club_city_normalize(text,text),public.club_cities() FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.club_city_key(text) TO anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.club_cities() TO service_role;
CREATE FUNCTION public._club332_city_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ BEGIN
 IF TG_OP='UPDATE' AND NEW.city IS NOT DISTINCT FROM OLD.city AND NEW.residence_country IS NOT DISTINCT FROM OLD.residence_country THEN RETURN NEW; END IF;
 NEW.city:=public.club_city_normalize(NEW.residence_country,NEW.city); RETURN NEW;
END $$;
CREATE TRIGGER club332_city_profile BEFORE INSERT OR UPDATE OF city,residence_country ON public.club_member_profiles FOR EACH ROW EXECUTE FUNCTION public._club332_city_profile();
CREATE FUNCTION public._club332_city_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$
DECLARE country text; city text; canonical text; BEGIN
 IF NEW.source IS DISTINCT FROM 'clube_newgang' OR NEW.company_id IS DISTINCT FROM '7c858982-6ccd-47ca-bd65-e0dd3eebf01c'::uuid THEN
   IF TG_OP='INSERT' THEN RETURN NEW; END IF;
   IF OLD.source IS DISTINCT FROM 'clube_newgang' OR OLD.company_id IS DISTINCT FROM '7c858982-6ccd-47ca-bd65-e0dd3eebf01c'::uuid THEN RETURN NEW; END IF;
 END IF;
 IF TG_OP='UPDATE' AND NEW.company_id IS NOT DISTINCT FROM OLD.company_id AND NEW.source IS NOT DISTINCT FROM OLD.source AND NEW.raw->'city' IS NOT DISTINCT FROM OLD.raw->'city' AND NEW.raw->'residence_country' IS NOT DISTINCT FROM OLD.raw->'residence_country' THEN RETURN NEW; END IF;
 IF NEW.raw ? 'city' AND NEW.raw->'city'<>'null'::jsonb AND jsonb_typeof(NEW.raw->'city') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'city_invalid'; END IF;
 city:=NEW.raw->>'city'; country:=NEW.raw->>'residence_country'; canonical:=public.club_city_normalize(country,city);
 IF NEW.raw ? 'city' THEN NEW.raw:=jsonb_set(NEW.raw,'{city}',coalesce(to_jsonb(canonical),'null'::jsonb)); END IF; RETURN NEW;
END $$;
CREATE TRIGGER club332_city_capture BEFORE INSERT OR UPDATE OF raw,source,company_id ON public.lead_capture FOR EACH ROW EXECUTE FUNCTION public._club332_city_capture();
REVOKE EXECUTE ON FUNCTION public._club332_city_profile(),public._club332_city_capture() FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.club_profile_confirm(p_site uuid,p_session_hash text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE m record; s club_profile_settings; p club_member_profiles; bd date; bc text; rc text; ct text; ev uuid; aid uuid; gained int:=0; BEGIN
 SELECT cm.* INTO m FROM club_member_sessions x JOIN club_members cm ON cm.id=x.member_id JOIN portal_sites ps ON ps.id=cm.site_id AND ps.company_id=cm.company_id WHERE x.site_id=p_site AND cm.site_id=p_site AND x.token_hash=p_session_hash AND x.purpose='access' AND x.expires_at>statement_timestamp() AND cm.confirmed_at IS NOT NULL AND ps.active AND ps.brand_key='newgang';
 IF NOT FOUND THEN RAISE EXCEPTION 'no_session'; END IF;
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('confirm','birth_date','birth_country','residence_country','city','phone','op')) THEN RAISE EXCEPTION 'profile_payload'; END IF;
 PERFORM _club_site_lock(p_site,false); PERFORM 1 FROM club_members WHERE id=m.id FOR NO KEY UPDATE;
 IF NOT EXISTS(SELECT 1 FROM club_member_sessions WHERE token_hash=p_session_hash AND site_id=p_site AND member_id=m.id AND purpose='access' AND expires_at>clock_timestamp()) THEN RAISE EXCEPTION 'no_session'; END IF;
 SELECT * INTO p FROM club_member_profiles WHERE member_id=m.id;
 SELECT * INTO s FROM club_profile_settings WHERE site_id=p_site AND company_id=m.company_id;
 IF p_payload->>'op'='clear' THEN
  IF p_payload<>jsonb_build_object('op','clear') THEN RAISE EXCEPTION 'profile_payload'; END IF;
  UPDATE club_member_profiles SET birth_date=NULL,birth_country=NULL,residence_country=NULL,city=NULL,updated_at=now() WHERE member_id=m.id;
  RETURN jsonb_build_object('ok',true,'awarded',0,'profile',club_profile_state(p_site,p_session_hash));
 END IF;
 IF p_payload ? 'op' OR p_payload->'confirm' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'profile_confirmation_required'; END IF;
 IF jsonb_typeof(p_payload->'birth_date') IS DISTINCT FROM 'string' OR (p_payload->>'birth_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'birth_date_invalid'; END IF;
 BEGIN bd:=(p_payload->>'birth_date')::date; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'birth_date_invalid'; END;
 IF NOT isfinite(bd) OR bd>(now() AT TIME ZONE 'Europe/Lisbon')::date THEN RAISE EXCEPTION 'birth_date_invalid'; END IF;
 IF bd>((now() AT TIME ZONE 'Europe/Lisbon')::date-interval '13 years')::date THEN RAISE EXCEPTION 'parental_flow_required'; END IF;
 IF jsonb_typeof(p_payload->'birth_country') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'country_invalid'; END IF;
 bc:=upper(btrim(p_payload->>'birth_country')); IF NOT EXISTS(SELECT 1 FROM club_profile_countries WHERE code=bc) THEN RAISE EXCEPTION 'country_invalid'; END IF;
 IF p_payload ? 'residence_country' AND p_payload->'residence_country'<>'null'::jsonb AND jsonb_typeof(p_payload->'residence_country') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'country_invalid'; END IF;
 rc:=nullif(upper(btrim(p_payload->>'residence_country')),'');
 IF rc IS NOT NULL AND NOT EXISTS(SELECT 1 FROM club_profile_countries WHERE code=rc) THEN RAISE EXCEPTION 'country_invalid'; END IF;
 IF p_payload ? 'city' AND p_payload->'city'<>'null'::jsonb AND jsonb_typeof(p_payload->'city') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'city_invalid'; END IF;
 ct:=public.club_city_normalize(rc,p_payload->>'city');
 IF p_payload ? 'phone' AND p_payload->'phone'<>'null'::jsonb AND (jsonb_typeof(p_payload->'phone') IS DISTINCT FROM 'string' OR (p_payload->>'phone') !~ '^\+[1-9][0-9]{7,14}$') THEN RAISE EXCEPTION 'phone_invalid'; END IF;
 IF NOT coalesce(s.enabled,false) THEN RAISE EXCEPTION 'profile_unavailable'; END IF;
 SELECT event_id INTO ev FROM portal_sites WHERE id=p_site AND company_id=m.company_id;
 IF ev IS NULL OR NOT EXISTS(SELECT 1 FROM events WHERE id=ev AND company_id=m.company_id) THEN RAISE EXCEPTION 'profile_event_invalid'; END IF;
 INSERT INTO club_member_profiles(member_id,site_id,company_id,birth_date,birth_country,residence_country,city) VALUES(m.id,p_site,m.company_id,bd,bc,rc,ct) ON CONFLICT(member_id) DO UPDATE SET birth_date=EXCLUDED.birth_date,birth_country=EXCLUDED.birth_country,residence_country=EXCLUDED.residence_country,city=EXCLUDED.city,updated_at=now();
 IF p_payload ? 'phone' THEN UPDATE club_members SET phone=p_payload->>'phone',updated_at=now() WHERE id=m.id; END IF;
 IF p.completed_at IS NULL THEN
  UPDATE club_member_profiles SET completed_at=now(),award_event_id=ev WHERE member_id=m.id;
  gained:=_club_award_core(m.id,'profile_complete',m.id::text,50,NULL); IF gained<>50 THEN RAISE EXCEPTION 'profile_credit_failed'; END IF;
  SELECT id INTO aid FROM club_points WHERE member_id=m.id AND rule_key='profile_complete';
  UPDATE club_member_profiles SET award_id=aid WHERE member_id=m.id;
 END IF;
 RETURN jsonb_build_object('ok',true,'awarded',gained,'profile',club_profile_state(p_site,p_session_hash));
END $$;
REVOKE EXECUTE ON FUNCTION public.club_profile_confirm(uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.club_profile_confirm(uuid,text,jsonb) TO service_role;
CREATE FUNCTION public.club_city_display(p_country text,p_city text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_catalog AS $$ SELECT CASE WHEN upper(coalesce(nullif(btrim(p_country),''),'PT')) IN ('PT','PORTUGAL') THEN coalesce((SELECT min(name) FROM public.portugal_municipalities WHERE public.club_city_key(name)=public.club_city_key(p_city)),nullif(btrim(p_city),'')) ELSE nullif(btrim(p_city),'') END $$;
REVOKE EXECUTE ON FUNCTION public.club_city_display(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.club_city_display(text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.clube_newgang_summary() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE v jsonb; v_today date:=(now() AT TIME ZONE 'Europe/Lisbon')::date; BEGIN
 PERFORM public._clube_newgang_assert_access();
 WITH b AS (SELECT (created_at AT TIME ZONE 'Europe/Lisbon')::date AS d,public.club_city_display(raw->>'residence_country',raw->>'city') AS city,coalesce(nullif(utm_source,''),'(direto)')||' / '||coalesce(nullif(utm_medium,''),'—')||' / '||coalesce(nullif(utm_campaign,''),'—') AS utm,public._clube_newgang_birth(raw) AS bd FROM public.lead_capture WHERE source='clube_newgang' AND public.row_belongs_to_current_company(company_id)),a AS (SELECT *,CASE WHEN bd IS NULL THEN 'sem data' ELSE CASE WHEN extract(year FROM age(v_today,bd))<18 THEN '<18' WHEN extract(year FROM age(v_today,bd))<25 THEN '18–24' WHEN extract(year FROM age(v_today,bd))<35 THEN '25–34' WHEN extract(year FROM age(v_today,bd))<45 THEN '35–44' ELSE '45+' END END AS faixa FROM b)
 SELECT jsonb_build_object('total',(SELECT count(*) FROM a),'today',(SELECT count(*) FROM a WHERE d=v_today),'last7',(SELECT count(*) FROM a WHERE d>v_today-7),'by_day',coalesce((SELECT jsonb_agg(jsonb_build_object('d',d,'n',n) ORDER BY d) FROM (SELECT d,count(*) n FROM a GROUP BY d)x),'[]'::jsonb),'by_city',coalesce((SELECT jsonb_agg(jsonb_build_object('k',k,'n',n) ORDER BY n DESC,k) FROM (SELECT coalesce(min(city),'(sem cidade)') k,count(*) n FROM a GROUP BY public.club_city_key(city) ORDER BY 2 DESC,1 LIMIT 10)x),'[]'::jsonb),'by_utm',coalesce((SELECT jsonb_agg(jsonb_build_object('k',utm,'n',n) ORDER BY n DESC,utm) FROM (SELECT utm,count(*) n FROM a GROUP BY 1 ORDER BY 2 DESC,1 LIMIT 20)x),'[]'::jsonb),'by_age',(SELECT jsonb_agg(jsonb_build_object('k',f,'n',(SELECT count(*) FROM a WHERE faixa=f)) ORDER BY o) FROM unnest(ARRAY['<18','18–24','25–34','35–44','45+','sem data']) WITH ORDINALITY AS t(f,o))) INTO v; RETURN v;
END $$;
REVOKE EXECUTE ON FUNCTION public.clube_newgang_summary() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.clube_newgang_summary() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.clube_newgang_list(p_search text DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS TABLE(id uuid,name text,email text,phone text,birth_date text,city text,postal_code text,consent_email boolean,consent_whatsapp boolean,utm_source text,utm_medium text,utm_campaign text,created_at timestamptz,total_count bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 PERFORM public._clube_newgang_assert_access(); RETURN QUERY
 SELECT l.id,l.name,l.email,l.phone,l.raw->>'birth_date',public.club_city_display(l.raw->>'residence_country',l.raw->>'city'),l.raw->>'postal_code',l.consent_email,l.consent_whatsapp,l.utm_source,l.utm_medium,l.utm_campaign,l.created_at,count(*) OVER () FROM public.lead_capture l WHERE l.source='clube_newgang' AND public.row_belongs_to_current_company(l.company_id) AND (coalesce(trim(p_search),'')='' OR l.name ILIKE '%'||trim(p_search)||'%' OR l.email ILIKE '%'||trim(p_search)||'%') ORDER BY l.created_at DESC,l.id LIMIT least(greatest(coalesce(p_limit,50),1),1000) OFFSET greatest(coalesce(p_offset,0),0);
END $$;
REVOKE EXECUTE ON FUNCTION public.clube_newgang_list(text,int,int) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.clube_newgang_list(text,int,int) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.club_profile_state(p_site uuid,p_session_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE m record; p club_member_profiles; s club_profile_settings; n int; BEGIN
 SELECT cm.* INTO m FROM club_member_sessions x JOIN club_members cm ON cm.id=x.member_id JOIN portal_sites ps ON ps.id=cm.site_id AND ps.company_id=cm.company_id WHERE x.site_id=p_site AND cm.site_id=p_site AND x.token_hash=p_session_hash AND x.purpose='access' AND x.expires_at>statement_timestamp() AND cm.confirmed_at IS NOT NULL AND ps.active AND ps.brand_key='newgang';
 IF NOT FOUND THEN RAISE EXCEPTION 'no_session'; END IF;
 SELECT * INTO p FROM club_member_profiles WHERE member_id=m.id;
 SELECT * INTO s FROM club_profile_settings WHERE site_id=p_site;
 SELECT coalesce(sum(points),0)::int INTO n FROM club_points WHERE member_id=m.id AND (rule_key='profile_complete' OR (rule_key='void' AND ref_id='profile_complete:'||m.id::text));
 RETURN jsonb_build_object('birth_date',p.birth_date,'birth_country',p.birth_country,'residence_country',p.residence_country,'city',p.city,'phone',m.phone,'complete',p.birth_date IS NOT NULL AND p.birth_country IS NOT NULL AND (p.residence_country IS DISTINCT FROM 'PT' OR p.city IS NOT NULL),'completed_at',p.completed_at,'reward_claimed',p.completed_at IS NOT NULL,'eligible',coalesce(s.enabled,false) AND p.completed_at IS NULL,'available',coalesce(s.enabled,false),'points',n,'reward_points',50,'version',s.version,'scope','adesao','whatsapp',jsonb_build_object('status','adapter_pending','editable',false));
END $$;
REVOKE EXECUTE ON FUNCTION public.club_profile_state(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.club_profile_state(uuid,text) TO service_role;